import { useState } from 'react';
import type { Task } from './task-tree.js';
import { TaskForm } from './task-form.js';
import styles from './ui.module.css';

/**
 * A single checkable task in a flat list. Ancestry is shown as small breadcrumb
 * chips instead of indentation, so lists stay easy to scan.
 * @param props.task - the leaf task
 * @param props.path - breadcrumb titles
 * @param props.color - project accent
 * @param props.onToggle - toggles done
 * @param props.onEdit - saves title/description (optional)
 * @param props.onRemove - deletes the task (optional)
 * @param props.onOpenPath - click handler for the breadcrumb (optional)
 */
export function CheckRow({
  task,
  path = [],
  color,
  onToggle,
  onEdit,
  onRemove,
  onOpenPath,
}: {
  task: Task;
  path?: string[];
  color?: string;
  onToggle: () => void;
  onEdit?: (v: { title: string; description: string }) => void;
  onRemove?: () => void;
  onOpenPath?: () => void;
}) {
  const [editing, setEditing] = useState(false);

  if (editing && onEdit) {
    return (
      <li className={styles.checkRow}>
        <div className={styles.checkBody}>
          <TaskForm initial={task} submitLabel="Save" onCancel={() => setEditing(false)} onSubmit={(v) => { onEdit(v); setEditing(false); }} />
        </div>
      </li>
    );
  }

  return (
    <li className={`${styles.checkRow} ${task.done ? styles.checkRowDone : ''}`}>
      <label className={styles.check}>
        <input type="checkbox" checked={task.done} onChange={onToggle} aria-label={task.title} />
        <span className={styles.checkBox} style={task.done ? { background: color, borderColor: color } : undefined}>
          {task.done ? '✓' : ''}
        </span>
      </label>
      <div className={styles.checkBody}>
        {path.length ? (
          <button type="button" className={styles.crumbs} onClick={onOpenPath} disabled={!onOpenPath}>
            {path.join(' › ')}
          </button>
        ) : null}
        <span className={styles.checkTitle}>{task.title}</span>
        {task.description ? <span className={styles.checkDesc}>{task.description}</span> : null}
      </div>
      {onEdit || onRemove ? (
        <div className={styles.rowTools}>
          {onEdit ? <button className={styles.iconBtn} title="Edit" aria-label="Edit task" onClick={() => setEditing(true)}>✎</button> : null}
          {onRemove ? <button className={styles.iconBtn} title="Delete" aria-label="Delete task" onClick={onRemove}>✕</button> : null}
        </div>
      ) : null}
    </li>
  );
}
